// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeStaticPrior.ParallelShape;
import org.junit.jupiter.api.Test;

/**
 * The parallel speed-up depends on the shape of the work: how many root rows the workers can split, whether the root
 * can be partitioned at all, and how large a partial table an aggregate has to merge afterwards.
 */
class LmdbNativeStaticPriorTest {

	@Test
	void aLargeRootScalesWithTheWorkers() {
		// 15000 people: a 3 s serial join ran in 460 ms on fifteen workers (6.5x)
		ParallelShape shape = new ParallelShape(true, 1_000_000D, false, 1D, 1_000_000D);
		assertThat(LmdbNativeStaticPrior.parallelSpeedup(shape, 15)).isCloseTo(6.6D, within(0.01D));
	}

	@Test
	void aTinyRootGainsNothing() {
		ParallelShape shape = new ParallelShape(true, 200D, false, 1D, 200D);
		assertThat(LmdbNativeStaticPrior.parallelSpeedup(shape, 8)).isEqualTo(1D);
	}

	@Test
	void anUnpartitionableRootGainsNothing() {
		// medical q12 (a UNION root under OPTIONALs) ran at 0.63x serial speed in parallel
		ParallelShape shape = new ParallelShape(false, 1_000_000D, false, 1D, 1_000_000D);
		assertThat(LmdbNativeStaticPrior.parallelSpeedup(shape, 8)).isEqualTo(1D);
	}

	@Test
	void aGlobalAggregateScalesLikeRowsAndMergesNothingWorthMentioning() {
		// medical q7: the serial kernel chosen at 2.6x regret while the flat 0.5 halved every parallel aggregate
		ParallelShape shape = new ParallelShape(true, 500_000D, true, 1D, 500_000D);
		assertThat(LmdbNativeStaticPrior.parallelSpeedup(shape, 8)).isCloseTo(3.52D, within(0.01D));
		assertThat(LmdbNativeStaticPrior.parallelMerge(shape, 8).expected(Feature.GROUP_UPDATE))
				.isLessThanOrEqualTo(8D);
	}

	@Test
	void aGroupedAggregateWithAsManyGroupsAsRowsPaysTheMergeOfEveryPartialTable() {
		// the parallel aggregates measured 0.38 to 0.70x serial speed on the FOAF stores: the merge eats the gain
		ParallelShape shape = new ParallelShape(true, 500_000D, true, 500_000D, 500_000D);
		assertThat(LmdbNativeStaticPrior.parallelMerge(shape, 8).expected(Feature.GROUP_UPDATE))
				.isGreaterThanOrEqualTo(500_000D);
	}

	@Test
	void theUnknownShapeKeepsTheFlatRule() {
		assertThat(LmdbNativeStaticPrior.parallelSpeedup(ParallelShape.UNKNOWN, 8))
				.isEqualTo(LmdbNativeStaticPrior
						.measuredParallelSpeedup(LmdbNativeAttemptMetrics.PATH_IR_KERNEL_PARALLEL, 8));
	}
}
